//! FreeANDIY branding: the paper-and-ink look of the light and dark themes, the UI font, the
//! app's mark and the upstream attribution shown in About.

use std::sync::Arc;

use egui::{Color32, Context, FontData, FontDefinitions, FontFamily, Id, Painter, Rect, TextureHandle, TextureOptions, Ui, Visuals};

use crate::theme::Tokens;

pub const APP_NAME: &str = "FreeANDIY Slides";
pub const OWNER: &str = "Free Andy Agency";
pub const UPSTREAM_NAME: &str = "DeckCraft";

const BLACK: Color32 = Color32::from_rgb(35, 31, 32);
const PAPER: Color32 = Color32::from_rgb(243, 242, 241);
const WHITE: Color32 = Color32::from_rgb(255, 255, 255);
const ROSE: Color32 = Color32::from_rgb(190, 62, 107);
const PINK: Color32 = Color32::from_rgb(234, 153, 153);
const YELLOW: Color32 = Color32::from_rgb(255, 217, 102);

/// `a` blended towards `b` by `t` (0..1), like ink at `t` opacity on paper.
const fn mix(a: Color32, b: Color32, t: f32) -> Color32 {
    Color32::from_rgb(channel(a.r(), b.r(), t), channel(a.g(), b.g(), t), channel(a.b(), b.b(), t))
}

const fn channel(x: u8, y: u8, t: f32) -> u8 {
    (x as f32 + (y as f32 - x as f32) * t + 0.5) as u8
}

/// Light is paper and ink, dark ink and paper: the stamp rose marks what is active, the yellow
/// highlighter what is selected. The canvas around the slide stays neutral grey.
pub fn tokens(t: Tokens) -> Tokens {
    if t.dark {
        let ink = |x: f32| mix(BLACK, PAPER, x);
        Tokens {
            chrome: mix(BLACK, Color32::BLACK, 0.25),
            card: BLACK,
            card_border: ink(0.20),
            text: PAPER,
            text_dim: ink(0.72),
            text_faint: ink(0.55),
            border: ink(0.22),
            separator: ink(0.16),
            hover: ink(0.12),
            pressed: ink(0.20),
            selected: mix(BLACK, ROSE, 0.40),
            accent: PINK,
            accent_text: BLACK,
            contextual: ROSE,
            field_bg: mix(BLACK, Color32::BLACK, 0.30),
            ..t
        }
    } else {
        let ink = |x: f32| mix(PAPER, BLACK, x);
        Tokens {
            chrome: ink(0.05),
            card: PAPER,
            card_border: ink(0.18),
            text: BLACK,
            text_dim: ink(0.70),
            text_faint: ink(0.55),
            border: ink(0.22),
            separator: ink(0.15),
            hover: ink(0.08),
            pressed: ink(0.15),
            selected: mix(PAPER, YELLOW, 0.55),
            accent: ROSE,
            accent_text: WHITE,
            contextual: mix(ROSE, BLACK, 0.20),
            field_bg: WHITE,
            ..t
        }
    }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same(2);
    v.menu_corner_radius = egui::CornerRadius::same(2);
    v.window_shadow = egui::epaint::Shadow::NONE;
    v.popup_shadow = egui::epaint::Shadow::NONE;
}

/// The interface font: IBM Plex Sans (SIL Open Font License 1.1; licence in
/// freeandiy/assets/fonts/) first, before the faces upstream uses. Desktop only: the web build
/// keeps its fonts, so the wasm does not grow.
pub fn ui_fonts(defs: &mut FontDefinitions) {
    #[cfg(not(target_arch = "wasm32"))]
    {
        let faces: [(FontFamily, &str, &'static [u8]); 2] = [
            (FontFamily::Proportional, "IBMPlexSans", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-Regular.ttf")),
            (FontFamily::Name("bold".into()), "IBMPlexSans-SemiBold", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-SemiBold.ttf")),
        ];
        for (family, key, bytes) in faces {
            defs.font_data.insert(key.to_string(), Arc::new(FontData::from_static(bytes)));
            defs.families.entry(family).or_default().insert(0, key.to_string());
        }
    }
    #[cfg(target_arch = "wasm32")]
    let _ = defs;
}

/// An embedded PNG as a mipmapped texture, decoded once per context.
fn png_texture(ctx: &Context, name: &str, bytes: &[u8]) -> Option<TextureHandle> {
    let id = Id::new(name);
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let img = deckcraft_render::decode_image(bytes)?;
    let image = egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw());
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture(name, image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

const MARK_PNG: &[u8] = include_bytes!("../../../assets/app-icon/freeandiy-slides-mark.png");
const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

/// The app's mark (its monogram tile) in `r`.
pub fn paint_mark(p: &Painter, r: Rect) {
    if let Some(tex) = png_texture(p.ctx(), "freeandiy-mark", MARK_PNG) {
        p.image(tex.id(), r, Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), Color32::WHITE);
    }
}

const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

/// The About tab's attribution: the Free Andy Agency seal and the upstream credit (MIT/Apache-2.0
/// require keeping the notices; the ArtCraft brand terms allow naming the origin in plain text).
pub fn about_attribution(ui: &mut Ui) {
    let t = Tokens::get(ui.ctx());
    if let Some(tex) = png_texture(ui.ctx(), "freeandiy-seal", SEAL_PNG) {
        ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(56.0, 56.0)));
    }
    let text = ATTRIBUTION.replace("{app}", APP_NAME).replace("{upstream}", UPSTREAM_NAME);
    ui.label(egui::RichText::new(text).size(11.0).color(t.text_dim));
    ui.label(egui::RichText::new(format!("© {OWNER}")).size(11.0).color(t.text_faint));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_marks_decode() {
        let ctx = Context::default();
        assert!(png_texture(&ctx, "seal", SEAL_PNG).is_some());
        assert!(png_texture(&ctx, "mark", MARK_PNG).is_some());
    }

    #[test]
    fn light_and_dark_are_paper_and_ink() {
        let (light, dark) = (Tokens::light(), Tokens::dark());
        assert_eq!((light.card, light.text, light.accent), (PAPER, BLACK, ROSE));
        assert_eq!((dark.card, dark.text, dark.accent), (BLACK, PAPER, PINK));
    }
}
